def generate_signals(df: pd.DataFrame) -> pd.Series:
    df = df.copy()
    if 'date' in df.columns:
        df['date'] = pd.to_datetime(df['date'])
        df = df.set_index('date')
    df = df.sort_index()
    df['ret_60'] = df['close'].pct_change(60)
    sig = pd.Series(0, index=df.index, dtype=int)
    for _, group in df.groupby(df.index.to_period('M')):
        idx = group.index[0]
        if pd.notna(df.loc[idx, 'ret_60']) and df.loc[idx, 'ret_60'] > 0:
            sig[df.index >= idx] = 1
    return sig

def generate_signals(df):
    df = df.copy()
    if 'date' in df.columns:
        df = df.set_index('date')
    if not isinstance(df.index, pd.DatetimeIndex):
        df.index = pd.to_datetime(df.index)
    df = df.sort_index()

    ret_120 = df['close'] / df['close'].shift(120) - 1

    months = df.index.to_period('M')
    is_month_start = months != months.shift(1)

    signals = pd.Series(0, index=df.index)
    signals[is_month_start & (ret_120 > 0)] = 1

    return signals.ffill().fillna(0)

def generate_signals(df: pd.DataFrame) -> pd.Series:
    ret = df['close'].pct_change(60)
    rank = ret.groupby(df['date']).rank(method='min', ascending=False)
    signal = (rank <= 2).astype(int)
    return signal.fillna(0)

def generate_signals(df: pd.DataFrame) -> pd.Series:
    sma_200 = df['close'].rolling(window=200).mean()
    return (df['close'] > sma_200).astype(int)

def generate_signals(df: pd.DataFrame) -> pd.Series:
    df = df.sort_values('date')
    mom = df['close'] / df['close'].shift(126) - 1
    monthly_sig = (mom.resample('ME', on='date').last() > 0).astype(int)
    signals = monthly_sig.reindex(df.index).ffill().fillna(0)
    return signals.astype(int)

def generate_signals(df: pd.DataFrame) -> pd.Series:
    ret_20 = df['close'].pct_change(20)
    signal = (ret_20 > 0).astype(int)
    return signal.fillna(0)
